import { STOPS, readProgress, saveProgress, jumpHeight, isDay } from './content.js';
import { heroArt, worldArt, planetArt, shipArt } from './art.js';
import { SpaceEngine } from './engine.js';
const $=selector=>document.querySelector(selector);
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Unavailable')}};}
let completed=readProgress(storage),persistent=true,paused=false,calm=matchMedia('(prefers-reduced-motion: reduce)').matches,sound=false,audioContext=null,labFrame=0,activeStop=null,toastTimer;
const expedition=$('#expedition'),discovery=$('#discovery'),notes=$('#notes');
$('#hero-art').innerHTML=heroArt();for(const id of ['history','weather','biology'])$(`#${id}-art`).innerHTML=worldArt(id);
const engine=new SpaceEngine($('#space'),{
  onNearby:id=>{const button=$('#investigate');button.hidden=!id;button.textContent=id?`Investigate ${STOPS.find(s=>s.id===id).name}  →`:'';},
  onArrive:id=>openDiscovery(id),
  onStatus:message=>{$('#flight-status').textContent=message;}
});
function tone(notes=[440,554,659]){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});notes.forEach((frequency,i)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),time=audioContext.currentTime+i*.09;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(.035,time+.02);gain.gain.exponentialRampToValueAtTime(.001,time+.3);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(time);oscillator.stop(time+.32);});}catch{/* Audio is optional. */}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function updateProgress(){
  $('#nav-count').textContent=completed.length;$('#flight-count').textContent=`${completed.length} / 3 discoveries`;
  $('#notebook-description').textContent=completed.length?`${completed.length} of 3 cosmic discoveries collected. A little wonder to take with you.`:'Every expedition leaves you with something to remember.';
  $('#launch').innerHTML=`${completed.length===3?'Explore again':completed.length?'Keep exploring':'Let’s explore'} <span aria-hidden="true">↗</span>`;
  $('#destinations').innerHTML=STOPS.map(s=>`<button class="destination ${completed.includes(s.id)?'complete':''}" data-destination="${s.id}" aria-label="Fly to ${s.name}${completed.includes(s.id)?', discovery collected':''}"><strong><span class="planet-dot" style="background:${s.color}"></span>${s.name}</strong><small>${completed.includes(s.id)?'✓ DISCOVERED':'FLY & DISCOVER ↗'}</small></button>`).join('');
  $('#destinations').querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>engine.flyTo(button.dataset.destination)));
  engine.completed=completed;engine.draw();
}
function syncPause(){engine.setPaused(paused||discovery.open);$('#pause').setAttribute('aria-pressed',String(paused));$('#pause').textContent=paused?'Resume':'Pause';$('#paused-overlay').hidden=!paused;}
function launch(){paused=false;expedition.showModal();document.body.style.overflow='hidden';engine.start(completed,calm);syncPause();$('#calm').setAttribute('aria-pressed',String(calm));$('#space').focus({preventScroll:true});tone([330,440]);}
$('#launch').addEventListener('click',launch);
$('#exit-flight').addEventListener('click',()=>expedition.close());
expedition.addEventListener('close',()=>{engine.stop();if(discovery.open)discovery.close();document.body.style.overflow='';});
$('#pause').addEventListener('click',()=>{paused=!paused;syncPause();if(!paused)$('#space').focus({preventScroll:true});});
$('#resume').addEventListener('click',()=>{paused=false;syncPause();$('#space').focus({preventScroll:true});});
$('#calm').addEventListener('click',()=>{calm=!calm;engine.setCalm(calm);$('#calm').setAttribute('aria-pressed',String(calm));$('#flight-status').textContent=calm?'Calm mode on. Simpler rendering, with instant experiment results.':'Calm mode off. Ready to explore.';});
$('#sound').addEventListener('click',()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').setAttribute('aria-label',sound?'Turn sound off':'Turn sound on');$('#sound').textContent=sound?'Sound on':'Sound off';tone([440,660]);});
$('#investigate').addEventListener('click',()=>{if(engine.nearby)openDiscovery(engine.nearby);});
document.querySelectorAll('[data-direction]').forEach(button=>{
  const key={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[button.dataset.direction];
  button.addEventListener('pointerdown',e=>{if(!engine.running)return;e.preventDefault();button.setPointerCapture(e.pointerId);engine.target=null;engine.keys.add(key);});
  for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>engine.keys.delete(key));
});
document.querySelectorAll('[data-open]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.open;if(id==='notes')renderNotes();$(`#${id}`).showModal();}));
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>$(`#${button.dataset.close}`).close()));
discovery.addEventListener('close',()=>{cancelAnimationFrame(labFrame);labFrame=0;activeStop=null;if(expedition.open){syncPause();$('#space').focus({preventScroll:true});}});

function dayLab(){return `<div class="lab"><span class="lab-label">EXPERIMENT 01 · FOLLOW THE LIGHT</span><svg viewBox="0 0 500 160" role="img" aria-label="Sunlight from the left lights half of Earth. Turn Earth to move the gold town marker from day to night."><defs><clipPath id="lab-earth-clip"><circle cx="300" cy="78" r="62"/></clipPath></defs><circle cx="65" cy="78" r="31" fill="#f2c461"/><g stroke="#b59860" stroke-width="2"><path d="M65 30V19m0 118v-11M17 78H6m118 0h-11M31 44l-8-8m76 76 8 8m-8-76 8-8m-76 76-8 8"/></g><path d="M125 50h83m-8-4 8 4-8 4m-75 24h83m-8-4 8 4-8 4m-75 24h83m-8-4 8 4-8 4" stroke="#c5b377" stroke-width="1.5" fill="none"/><g clip-path="url(#lab-earth-clip)"><circle cx="300" cy="78" r="62" fill="#80bfba"/><g id="earth-land"><path d="m246 60 21-22 28 10-8 22 12 20-18 13-28-22Zm61-45 29 25-12 21 24 18-19 37-21 18-9-27 11-24-15-22Z" fill="#b8cd85"/></g><path d="M300 10h80v140h-80Z" fill="#142e39" opacity=".76"/></g><circle cx="300" cy="78" r="62" fill="none" stroke="#659c9b"/><circle id="town" cx="250" cy="78" r="6" fill="#f2c461" stroke="#f9edc5" stroke-width="2"/><text x="409" y="74" fill="#f2c461" font-size="13" font-family="Arial" id="day-label">DAY</text><text x="409" y="92" fill="#b3c9c0" font-size="9" font-family="Arial">at your town</text><text x="43" y="135" fill="#bed0c2" font-size="10" font-family="Arial">SUN</text></svg><div class="lab-controls"><label for="earth-turn">Turn Earth</label><input type="range" id="earth-turn" min="0" max="360" value="20" step="1"><output id="earth-angle" for="earth-turn">20°</output></div><p class="lab-caption">View from above the North Pole. The gold dot is your town. Move it into the dark.</p></div>`;}
function moonLab(){return `<div class="lab"><span class="lab-label">EXPERIMENT 02 · SAME JUMP, DIFFERENT WORLD</span><svg viewBox="0 0 500 160" role="img" aria-label="Two identical explorers jump with the same take-off speed on Earth and the Moon. Weaker lunar gravity allows a higher jump."><path d="M30 130h180M288 130h180" stroke="#648d83" stroke-width="2"/><path d="M30 118h180M288 57h180" stroke="#63776a" stroke-width="1" stroke-dasharray="3 5"/><text x="114" y="152" fill="#b8ccbf" font-size="10" font-family="Arial">EARTH</text><text x="362" y="152" fill="#b8ccbf" font-size="10" font-family="Arial">MOON</text><g id="earth-jumper" transform="translate(129 126)"><path d="M-5 0v-14h10V0m-11-10-6 5m18-5 6 5" stroke="#b9d0b7" stroke-width="4" fill="none"/><circle cy="-22" r="8" fill="#e4ead4"/><path d="M-5-24h10v5H-5" fill="#659f9e"/></g><g id="moon-jumper" transform="translate(379 126)"><path d="M-5 0v-14h10V0m-11-10-6 5m18-5 6 5" stroke="#b9d0b7" stroke-width="4" fill="none"/><circle cy="-22" r="8" fill="#e4ead4"/><path d="M-5-24h10v5H-5" fill="#659f9e"/></g><text x="34" y="105" fill="#a6bfaf" font-size="9" font-family="Arial">1×</text><text x="294" y="22" fill="#f2c461" font-size="9" font-family="Arial">ABOUT 6× HIGHER</text></svg><div class="lab-controls"><button class="experiment-button" id="jump">Try a jump ↑</button><span id="jump-observation" style="font-size:11px;color:#c3d0b9">One push. Two different pulls.</span></div><p class="lab-caption">Same take-off speed, no air resistance. Gravity and jumps are simplified; heights share one scale.</p></div>`;}
function marsLab(){return `<div class="lab"><span class="lab-label">EXPERIMENT 03 · A CHANGE IN THE DUST</span><svg viewBox="0 0 500 160" role="img" aria-label="An iron-rich rock changes from grey to rusty red as oxidation increases."><path d="M74 131h351" stroke="#4e706d"/><g id="mars-rock" fill="#9c9d8e"><path d="m165 112-7-45 28-35 53 6 27-17 50 37 24 53-30 22-114-2Z"/><path d="m164 68 47 5 28-35M211 73l-15 58m15-58 55 17 50-32m-50 32 44 43" stroke="#263e3d" stroke-opacity=".25" stroke-width="3" fill="none"/></g><circle cx="229" cy="109" r="6" fill="#263e3d" opacity=".15"/><circle cx="286" cy="57" r="5" fill="#263e3d" opacity=".15"/><g fill="#e8c17b"><path d="m116 48 4 8 8 4-8 4-4 8-4-8-8-4 8-4m246 18 3 6 6 3-6 3-3 6-3-6-6-3 6-3"/></g></svg><div class="lab-controls"><label for="rust">Oxidation</label><input type="range" id="rust" min="0" max="100" value="0"><output id="rust-label" for="rust">Not rusty</output></div><p class="lab-caption">Iron minerals react with oxygen in other substances to form rust. A model of the colour change, not a real timescale.</p></div>`;}
const questions={
 earth:{lead:'Our town is marked with a gold dot. Turn Earth and watch what happens when the town faces away from the Sun.',prompt:'What makes day turn into night?',answers:['The Sun switches its light off.','Earth spins, carrying our town away from sunlight.','The Moon covers the Sun every evening.'],correct:1,success:'You found it! Earth keeps turning. Our town moves from the sunny side to the dark side.',retry:'Look at the Sun: it keeps shining. Try turning Earth again and follow the gold dot.'},
 moon:{lead:'Give both explorers the same take-off speed. Make a prediction, then try the jump. Who will go higher?',prompt:'Why does our explorer jump higher on the Moon?',answers:['Their legs become stronger on the Moon.','There is no gravity on the Moon.','The Moon’s weaker gravity pulls them down less.'],correct:2,success:'Exactly. The Moon has gravity, but its pull at the surface is much weaker than Earth’s.',retry:'Both explorers get the same push, and both fall back down. Think about how strongly each world pulls.'},
 mars:{lead:'There’s a clue hidden in the dust. Turn up oxidation and watch our iron-rich rock change colour.',prompt:'What gives much of Mars its reddish colour?',answers:['Iron minerals have oxidised, forming rust.','The surface is covered in red plants.','Mars glows red because it is very hot.'],correct:0,success:'Mystery solved. The reddish dust contains oxidised iron — a kind of rust.',retry:'Watch the rock as oxidation increases. The colour comes from a chemical change in its minerals.'}
};
function openDiscovery(id){
  if(discovery.open)return;cancelAnimationFrame(labFrame);activeStop=id;engine.target=null;engine.keys.clear();engine.vx=engine.vy=0;
  const stop=STOPS.find(s=>s.id===id),q=questions[id];let observed=false,correct=false;
  discovery.innerHTML=`<button class="close-dialog" id="close-discovery" aria-label="Return to your ship">×</button><p class="eyebrow">${stop.name.toUpperCase()} · ${stop.subtitle.toUpperCase()}</p><h2 id="discovery-title">${stop.question}</h2><p class="discovery-lead">${q.lead}</p>${id==='earth'?dayLab():id==='moon'?moonLab():marsLab()}<p class="question" id="question-label">${q.prompt}</p><div class="answers" role="group" aria-labelledby="question-label">${q.answers.map((a,i)=>`<button class="answer" data-answer="${i}" disabled><span class="answer-letter">${String.fromCharCode(65+i)}</span>${a}</button>`).join('')}</div><div class="feedback" id="feedback" role="status">Try the experiment above to unlock your discovery.</div><div class="discovery-footer"><a class="source-link" href="${stop.source}" target="_blank" rel="noopener noreferrer">${stop.sourceLabel} ↗</a><button class="button button-dark collect-button" id="collect" disabled>Save discovery <span aria-hidden="true">↗</span></button></div>`;
  const markObserved=()=>{if(observed)return;observed=true;discovery.querySelectorAll('.answer').forEach(b=>b.disabled=false);$('#feedback').textContent='What did you notice? Choose an explanation.';};
  $('#close-discovery').addEventListener('click',()=>discovery.close());
  discovery.querySelectorAll('.answer').forEach(button=>button.addEventListener('click',()=>{if(correct)return;const chosen=Number(button.dataset.answer);correct=chosen===q.correct;$('#feedback').classList.toggle('retry',!correct);$('#feedback').textContent=correct?q.success:q.retry;if(correct){button.classList.add('correct');$('#collect').disabled=false;discovery.querySelectorAll('.answer').forEach(b=>b.disabled=true);button.disabled=false;tone([440,554]);}}));
  $('#collect').addEventListener('click',()=>{if(!correct)return;const fresh=!completed.includes(id);if(fresh){completed.push(id);persistent=saveProgress(storage,completed);}updateProgress();tone();if(completed.length===3)showCompletion();else{discovery.close();const next=STOPS.find(s=>!completed.includes(s.id));$('#flight-status').textContent=`${stop.badge} saved${persistent?'':' for this visit'}. Next stop: ${next.name}?`;}});
  if(id==='earth'){
    const turn=()=>{const angle=Number($('#earth-turn').value),r=angle*Math.PI/180;$('#earth-land').setAttribute('transform',`rotate(${angle} 300 78)`);$('#town').setAttribute('cx',String(300-50*Math.cos(r)));$('#town').setAttribute('cy',String(78-50*Math.sin(r)));$('#earth-angle').textContent=`${angle}°`;$('#day-label').textContent=isDay(angle)?'DAY':'NIGHT';if(!isDay(angle))markObserved();};$('#earth-turn').addEventListener('input',turn);turn();
  }else if(id==='moon'){
    const pose=(earth,moon)=>{$('#earth-jumper')?.setAttribute('transform',`translate(129 ${126-earth*14})`);$('#moon-jumper')?.setAttribute('transform',`translate(379 ${126-moon*14})`);};
    $('#jump').addEventListener('click',()=>{cancelAnimationFrame(labFrame);$('#jump').disabled=true;$('#jump-observation').textContent='Watch the Moon explorer…';let start=0,last=0,elapsed=0;const finish=()=>{markObserved();$('#jump').disabled=false;$('#jump').textContent='Jump again ↑';$('#jump-observation').textContent='About six times as high on the Moon.';};if(calm){pose(jumpHeight(9.81,4/9.81),jumpHeight(1.62,4/1.62));finish();return;}const animate=time=>{if(!discovery.open||activeStop!=='moon')return;if(!start){start=time;last=time;}if(!document.hidden)elapsed+=Math.min((time-last)/1000,.05);last=time;pose(jumpHeight(9.81,elapsed),jumpHeight(1.62,elapsed));if(elapsed>2.5)markObserved();if(elapsed<5.05)labFrame=requestAnimationFrame(animate);else finish();};labFrame=requestAnimationFrame(animate);});
  }else{
    $('#rust').addEventListener('input',()=>{const v=Number($('#rust').value)/100;const base=[156,157,142],rust=[222,132,91];$('#mars-rock').setAttribute('fill',`rgb(${base.map((n,i)=>Math.round(n+(rust[i]-n)*v)).join(',')})`);$('#rust-label').textContent=v>.7?'Rusty red':v>.25?'Changing…':'Not rusty';if(v>.7)markObserved();});
  }
  discovery.showModal();syncPause();
}
function showCompletion(){
  cancelAnimationFrame(labFrame);activeStop=null;
  discovery.innerHTML=`<button class="close-dialog" id="close-discovery" aria-label="Return to your ship">×</button><div class="completion-view"><p class="eyebrow">THREE LITTLE DISCOVERIES. ONE BIG ADVENTURE.</p><div class="completion-illustration">${shipArt()}</div><h2 id="discovery-title">A universe more curious.</h2><p>You followed the sunlight, felt the pull of gravity,<br>and found the story in a rusty rock.</p><div class="completion-stamps">${STOPS.map(s=>`<span>✓ ${s.badge}</span>`).join('')}</div><p class="fine-print">${persistent?'All three discoveries are tucked into your field notes.':'Your discoveries are available for this visit. This browser could not save them.'}</p><div class="completion-actions"><button class="button button-dark" id="read-notes">Open my field notes ↗</button><button class="button button-yellow" id="keep-flying">Keep flying →</button></div></div>`;
  $('#close-discovery').addEventListener('click',()=>discovery.close());$('#keep-flying').addEventListener('click',()=>discovery.close());$('#read-notes').addEventListener('click',()=>{discovery.close();expedition.close();renderNotes();notes.showModal();});$('#read-notes').focus();
}
function renderNotes(){
  notes.innerHTML=`<button class="close-dialog" id="close-notes" aria-label="Close field notes">×</button><p class="eyebrow">SOUVENIRS FROM THE COSMIC NEIGHBOURHOOD</p><h2 id="notes-title">Your field notes<span style="color:#b5824e">.</span></h2><p class="notes-intro">${completed.length?`${completed.length} of 3 discoveries. Small things to remember. Big things to wonder about.`:'A fresh page and a whole universe ahead. Your discoveries will appear here as you explore.'}</p>${STOPS.map(s=>`<article class="note-entry ${completed.includes(s.id)?'':'locked'}"><div class="note-icon" aria-hidden="true">${planetArt(s.id)}</div><div><h3>${completed.includes(s.id)?s.badge:s.name+' · still to discover'}</h3><p>${completed.includes(s.id)?s.note:s.question}</p>${completed.includes(s.id)?`<a class="source-link" href="${s.source}" target="_blank" rel="noopener noreferrer">${s.sourceLabel} ↗</a>`:''}</div></article>`).join('')}<div class="notes-bottom"><span>${persistent?'Saved on this browser. No account needed.':'Saved for this visit only. Browser storage is unavailable.'}</span><button class="button button-dark" id="notes-explore">${completed.length?'Back to exploring':'Start exploring'} ↗</button></div>${completed.length?'<button class="reset-progress" id="reset-progress">Start a fresh notebook</button>':''}`;
  $('#close-notes').addEventListener('click',()=>notes.close());$('#notes-explore').addEventListener('click',()=>{notes.close();launch();});
  if($('#reset-progress')){let armed=false;$('#reset-progress').addEventListener('click',()=>{if(!armed){armed=true;$('#reset-progress').textContent='Clear all three discoveries? Click again to confirm.';return;}completed=[];persistent=saveProgress(storage,completed);updateProgress();renderNotes();$('#notes-explore').focus();});}
}
updateProgress();
